    16→class WhatsAppController extends Controller
    17→{
    18→    /**
    19→     * Constructor.
    20→     *
    21→     * @param WhatsAppService $servicio Servicio de WhatsApp.
    22→     * @return void
    23→     * @author Esperanza Olivo
    24→     */
    25→    public function __construct(protected WhatsAppService $servicio) {}
    26→
    27→    /**
    28→     * Obtener plantillas de WhatsApp aprobadas.
    29→     *
    30→     * @param Request $request Contenido de la petición.
    31→     * @return JsonResponse
    32→     * @author Esperanza Olivo
    33→     */
    34→    public function plantillas(Request $request): JsonResponse
    35→    {
    36→        try {
    37→            if (!$this->servicio->estaConfigurado()) {
    38→                return new JsonResponse([
    39→                    'message' => 'La integración de WhatsApp no está configurada.',
    40→                    'data'    => []
    41→                ], 400);
    42→            }
    43→
    44→            $linea_id = $request->input('linea_id');
    45→            $plantillas = $this->servicio->obtenerPlantillasAprobadas($linea_id);
    46→
    47→            return new JsonResponse([
    48→                'message' => 'Plantillas obtenidas correctamente.',
    49→                'data'    => $plantillas->values()->toArray()
    50→            ], 200);
    51→        } catch (Exception $error) {
    52→            return new JsonResponse([
    53→                'message' => 'Error al obtener plantillas.',
    54→                'errors'  => $error->getMessage()
    55→            ], 500);
    56→        }
    57→    }
    58→
    59→    /**
    60→     * Obtener una plantilla específica.
    61→     *
    62→     * @param int $plantilla_id ID de la plantilla.
    63→     * @return JsonResponse
    64→     * @author Esperanza Olivo
    65→     */
    66→    public function plantilla(int $plantilla_id): JsonResponse
    67→    {
    68→        try {
    69→            if (!$this->servicio->estaConfigurado()) {
    70→                return new JsonResponse([
    71→                    'message' => 'La integración de WhatsApp no está configurada.',
    72→                    'data'    => null
    73→                ], 400);
    74→            }
    75→
    76→            $plantilla = $this->servicio->obtenerPlantilla($plantilla_id);
    77→
    78→            if (!$plantilla) {
    79→                return new JsonResponse([
    80→                    'message' => 'Plantilla no encontrada.',
    81→                    'data'    => null
    82→                ], 404);
    83→            }
    84→
    85→            return new JsonResponse([
    86→                'message' => 'Plantilla obtenida correctamente.',
    87→                'data'    => $plantilla
    88→            ], 200);
    89→        } catch (Exception $error) {
    90→            return new JsonResponse([
    91→                'message' => 'Error al obtener la plantilla.',
    92→                'errors'  => $error->getMessage()
    93→            ], 500);
    94→        }
    95→    }
    96→
    97→    /**
    98→     * Enviar mensaje de WhatsApp.
    99→     *
   100→     * @param Request $request Contenido de la petición.
   101→     * @return JsonResponse
   102→     * @author Esperanza Olivo
   103→     */
   104→    public function enviar(Request $request): JsonResponse
   105→    {
   106→        $request->validate([
   107→            'plantilla_id' => 'required|integer',
   108→            'telefono'    => 'required|string',
   109→            'variables'   => 'nullable|array',
   110→            'linea_id'     => 'nullable|integer'
   111→        ]);
   112→
   113→        try {
   114→            if (!$this->servicio->estaConfigurado()) {
   115→                return new JsonResponse([
   116→                    'message' => 'La integración de WhatsApp no está configurada.'
   117→                ], 400);
   118→            }
   119→
   120→            $resultado = $this->servicio->enviarMensajePlantilla(
   121→                $request->input('plantilla_id'),
   122→                $request->input('telefono'),
   123→                $request->input('variables', []),
   124→                $request->input('linea_id')
   125→            );
   126→
   127→            return new JsonResponse([
   128→                'message' => 'Mensaje enviado correctamente.',
   129→                'data'    => $resultado
   130→            ], 200);
   131→        } catch (Exception $error) {
   132→            return new JsonResponse([
   133→                'message' => 'Error al enviar mensaje.',
   134→                'errors'  => $error->getMessage()
   135→            ], 500);
   136→        }
   137→    }
   138→
   139→    /**
   140→     * Verificar estado de configuración de WhatsApp.
   141→     *
   142→     * @return JsonResponse
   143→     * @author Esperanza Olivo
   144→     */
   145→    public function estado(): JsonResponse
   146→    {
   147→        return new JsonResponse([
   148→            'configurado' => $this->servicio->estaConfigurado()
   149→        ], 200);
   150→    }
   151→
   152→    /**
   153→     * Reenviar notificaciones de WhatsApp fallidas.
   154→     *
   155→     * @param Request $request Contenido de la petición.
   156→     * @return JsonResponse
   157→     * @author Esperanza Olivo
   158→     */
   159→    public function reenviarNotificaciones(Request $request): JsonResponse
   160→    {
   161→        $request->validate([
   162→            'vacante_id'                        => 'required|integer',
   163→            'candidatos'                        => 'required|array',
   164→            'candidatos.*.etapa_vacante_usuario_id' => 'required|integer',
   165→            'candidatos.*.telefono'             => 'required|string'
   166→        ]);
   167→
   168→        try {
   169→            if (!$this->servicio->estaConfigurado()) {
   170→                return new JsonResponse([
   171→                    'message' => 'La integración de WhatsApp no está configurada.'
   172→                ], 400);
   173→            }
   174→
   175→            $resultado = $this->servicio->reenviarNotificaciones(
   176→                $request->input('vacante_id'),
   177→                $request->input('candidatos')
   178→            );
   179→
   180→            return new JsonResponse([
   181→                'message' => 'Reenvío completado.',
   182→                'data'    => $resultado
   183→            ], 200);
   184→        } catch (Exception $error) {
   185→            return new JsonResponse([
   186→                'message' => 'Error al reenviar notificaciones.',
   187→                'errors'  => $error->getMessage()
   188→            ], 500);
   189→        }
   190→    }
   191→
   192→    /**
   193→     * Obtener notificaciones fallidas de una vacante.
   194→     *
   195→     * @param int $vacante_id ID de la vacante.
   196→     * @return JsonResponse
   197→     * @author Esperanza Olivo
   198→     */
   199→    public function notificacionesFallidas(int $vacante_id): JsonResponse
   200→    {
   201→        try {
   202→            $notificaciones = $this->servicio->obtenerNotificacionesFallidas($vacante_id);
   203→
   204→            return new JsonResponse([
   205→                'exito'          => true,
   206→                'message'        => 'Notificaciones obtenidas correctamente.',
   207→                'notificaciones' => $notificaciones
   208→            ], 200);
   209→        } catch (Exception $error) {
   210→            return new JsonResponse([
   211→                'exito'   => false,
   212→                'message' => 'Error al obtener notificaciones.',
   213→                'errors'  => $error->getMessage()
   214→            ], 500);
   215→        }
   216→    }
   217→
   218→    /**
   219→     * Reenviar notificación individual a un candidato.
   220→     *
   221→     * @param Request $request Contenido de la petición.
   222→     * @return JsonResponse
   223→     * @author Esperanza Olivo
   224→     */
   225→    public function reenviarIndividual(Request $request): JsonResponse
   226→    {
   227→        $request->validate([
   228→            'vacante_id'               => 'required|integer',
   229→            'etapa_vacante_usuario_id' => 'required|integer',
   230→            'telefono'                 => 'required|string'
   231→        ]);
   232→
   233→        try {
   234→            if (!$this->servicio->estaConfigurado()) {
   235→                return new JsonResponse([
   236→                    'exito'   => false,
   237→                    'message' => 'La integración de WhatsApp no está configurada.'
   238→                ], 400);
   239→            }
   240→
   241→            $resultado = $this->servicio->reenviarNotificacionIndividual(
   242→                $request->input('vacante_id'),
   243→                $request->input('etapa_vacante_usuario_id'),
   244→                $request->input('telefono')
   245→            );
   246→
   247→            return new JsonResponse([
   248→                'exito'   => $resultado['exito'],
   249→                'message' => $resultado['exito'] ? 'Notificación enviada correctamente.' : 'Error al enviar notificación.',
   250→                'error'   => $resultado['error'] ?? null
   251→            ], $resultado['exito'] ? 200 : 400);
   252→        } catch (Exception $error) {
   253→            return new JsonResponse([
   254→                'exito'   => false,
   255→                'message' => 'Error al reenviar notificación.',
   256→                'error'   => $error->getMessage()
   257→            ], 500);
   258→        }
   259→    }
   260→}
