     3→namespace App\Http\Services\Notificaciones;
     4→
     5→use App\Http\Repositories\Vacantes\EtapaVacanteUsuarioRepository;
     6→use App\Http\Repositories\Vacantes\VacanteRepository;
     7→use App\Http\Services\Usuarios\TokenAccesoService;
     8→use Exception;
     9→use GuzzleHttp\Client;
    10→use GuzzleHttp\Exception\RequestException;
    11→use Illuminate\Support\Collection;
    12→use Illuminate\Support\Facades\Auth;
    13→use Illuminate\Support\Facades\Log;
    14→use App\Models\Configuraciones\NotificacionWhatsApp;
    15→use App\Models\Vacantes\EtapaVacante;
    16→use Carbon\Carbon;
    17→
    18→/**
    19→ * Servicio para integración con la API de WhatsApp.
    20→ *
    21→ * @author Esperanza Olivo
    22→ */
    23→class WhatsAppService
    24→{
    25→    /**
    26→     * Cliente HTTP.
    27→     *
    28→     * @var Client
    29→     */
    30→    protected Client $cliente;
    31→
    32→    /**
    33→     * URL base de la API.
    34→     *
    35→     * @var string
    36→     */
    37→    protected string $api_url;
    38→
    39→    /**
    40→     * Token de autenticación.
    41→     *
    42→     * @var string
    43→     */
    44→    protected string $api_token;
    45→
    46→    /**
    47→     * API Key.
    48→     *
    49→     * @var string
    50→     */
    51→    protected string $api_key;
    52→
    53→    /**
    54→     * ID de línea de WhatsApp por defecto.
    55→     *
    56→     * @var int
    57→     */
    58→    protected int $linea_id;
    59→
    60→    /**
    61→     * Constructor.
    62→     *
    63→     * @return void
    64→     * @author Esperanza Olivo
    65→     */
    66→    public function __construct()
    67→    {
    68→        $this->api_url   = config('whatsapp.api_url');
    69→        $this->api_token = config('whatsapp.api_token');
    70→        $this->api_key   = config('whatsapp.api_key');
    71→        $this->linea_id   = config('whatsapp.linea_id');
    72→
    73→        $this->cliente = new Client([
    74→            'timeout' => config('whatsapp.timeout', 30),
    75→            'headers' => [
    76→                'Content-Type'  => 'application/json',
    77→                'Accept'        => 'application/json',
    78→                'Authorization' => 'Bearer ' . $this->api_token
    79→            ]
    80→        ]);
    81→    }
    82→
    83→    /**
    84→     * Verificar si la configuración de WhatsApp está completa.
    85→     *
    86→     * @return bool
    87→     * @author Esperanza Olivo
    88→     */
    89→    public function estaConfigurado(): bool
    90→    {
    91→        return !empty($this->api_url) && !empty($this->api_token) && !empty($this->api_key);
    92→    }
    93→
    94→    /**
    95→     * Obtener plantillas disponibles.
    96→     *
    97→     * @param array $filtros Filtros opcionales (lineId, status, limit, offset).
    98→     * @return array
    99→     * @throws Exception Si hay un error en la petición.
   100→     * @author Esperanza Olivo
   101→     */
   102→    public function obtenerPlantillas(array $filtros = []): array
   103→    {
   104→        if (!$this->estaConfigurado()) {
   105→            throw new Exception('La configuración de WhatsApp no está completa.');
   106→        }
   107→
   108→        $parametros = array_merge(['apiKey' => $this->api_key], $filtros);
   109→
   110→        if (!isset($parametros['lineId']) && $this->linea_id) {
   111→            $parametros['lineId'] = $this->linea_id;
   112→        }
   113→
   114→        try {
   115→            $respuesta = $this->cliente->get($this->api_url . '/templates', [
   116→                'query' => $parametros
   117→            ]);
   118→
   119→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   120→
   121→            if (!$datos['success']) {
   122→                throw new Exception($datos['message'] ?? 'Error al obtener plantillas');
   123→            }
   124→
   125→            return $datos['data'] ?? [];
   126→        } catch (RequestException $error) {
   127→            $this->manejarError($error, 'obtener plantillas');
   128→        }
   129→
   130→        return [];
   131→    }
   132→
   133→    /**
   134→     * Obtener plantillas aprobadas.
   135→     *
   136→     * @param int|null $linea_id ID de la línea de WhatsApp (opcional).
   137→     * @return Collection
   138→     * @throws Exception Si hay un error en la petición.
   139→     * @author Esperanza Olivo
   140→     */
   141→    public function obtenerPlantillasAprobadas(?int $linea_id = null): Collection
   142→    {
   143→        $filtros = ['status' => 'approved'];
   144→
   145→        if ($linea_id) {
   146→            $filtros['lineId'] = $linea_id;
   147→        }
   148→
   149→        $respuesta = $this->obtenerPlantillas($filtros);
   150→
   151→        return collect($respuesta['templates'] ?? []);
   152→    }
   153→
   154→    /**
   155→     * Obtener una plantilla por su ID.
   156→     *
   157→     * @param int $id ID de la plantilla.
   158→     * @return array|null
   159→     * @author Esperanza Olivo
   160→     */
   161→    public function obtenerPlantilla(int $id): ?array
   162→    {
   163→        $plantillas = $this->obtenerPlantillasAprobadas();
   164→
   165→        return $plantillas->firstWhere('id', $id);
   166→    }
   167→
   168→    /**
   169→     * Obtener el ID de una plantilla por su nombre.
   170→     *
   171→     * @param string $nombre Nombre de la plantilla.
   172→     * @return int|null ID de la plantilla o null si no se encuentra.
   173→     * @author Esperanza Olivo
   174→     */
   175→    public function obtenerIdPlantillaPorNombre(string $nombre): ?int
   176→    {
   177→        $plantillas = $this->obtenerPlantillasAprobadas();
   178→        $plantilla = $plantillas->firstWhere('name', $nombre);
   179→
   180→        return $plantilla ? $plantilla['id'] : null;
   181→    }
   182→
   183→    /**
   184→     * Enviar mensaje de plantilla.
   185→     *
   186→     * @param int $plantilla_id ID de la plantilla.
   187→     * @param string $telefono Número de teléfono del destinatario (con código de país).
   188→     * @param array $variables Valores de las variables de la plantilla.
   189→     * @param int|null $linea_id ID de la línea de WhatsApp (opcional).
   190→     * @param array $parametros_encabezado Parámetros del header (opcional).
   191→     * @param array $parametros_botones Parámetros de botones (opcional).
   192→     * @param array $contexto Datos adicionales para el registro (usuario_id, modelo, modelo_id, tipo, etc.).
   193→     * @return array Resultado con 'exito', 'mensaje_id', 'notificacion_id' y datos adicionales.
   194→     * @author Esperanza Olivo
   195→     */
   196→    public function enviarMensajePlantilla(
   197→        int $plantilla_id,
   198→        string $telefono,
   199→        array $variables = [],
   200→        ?int $linea_id = null,
   201→        array $parametros_encabezado = [],
   202→        array $parametros_botones = [],
   203→        array $contexto = []
   204→    ): array {
   205→        if (!$this->estaConfigurado()) {
   206→            throw new Exception('La configuración de WhatsApp no está completa.');
   207→        }
   208→
   209→        $telefono_limpio = $this->limpiarNumeroTelefono($telefono);
   210→
   211→        $plantilla_nombre = null;
   212→        try {
   213→            $plantilla = $this->obtenerPlantilla($plantilla_id);
   214→            $plantilla_nombre = $plantilla['name'] ?? null;
   215→        } catch (Exception $e) {
   216→        }
   217→
   218→        $notificacion = NotificacionWhatsApp::create([
   219→            'vacante_id'              => $contexto['vacante_id'] ?? null,
   220→            'etapa_vacante_usuario_id'=> $contexto['etapa_vacante_usuario_id'] ?? null,
   221→            'telefono'                => $telefono_limpio,
   222→            'enviado_por'             => Auth::id(),
   223→            'plantilla_id'            => $plantilla_id,
   224→            'plantilla_nombre'        => $plantilla_nombre,
   225→            'variables'               => $variables,
   226→            'estado'                  => NotificacionWhatsApp::ESTADO_PENDIENTE,
   227→            'tipo'                    => $contexto['tipo'] ?? NotificacionWhatsApp::TIPO_GENERAL,
   228→            'metadata'                => $contexto['metadata'] ?? null
   229→        ]);
   230→
   231→        $payload = [
   232→            'apiKey'         => $this->api_key,
   233→            'templateId'     => $plantilla_id,
   234→            'lineId'         => $linea_id ?? $this->linea_id,
   235→            'to'             => $telefono_limpio,
   236→            'variableValues' => $variables,
   237→            'headerParams'   => $parametros_encabezado,
   238→            'buttonParams'   => $parametros_botones
   239→        ];
   240→
   241→        try {
   242→            $respuesta = $this->cliente->post($this->api_url . '/messages/send-template', [
   243→                'json' => $payload
   244→            ]);
   245→
   246→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   247→
   248→            if (!$datos['success']) {
   249→                $mensaje_error = $datos['message'] ?? 'Error al enviar mensaje';
   250→                $notificacion->marcarComoFallido($mensaje_error);
   251→                throw new Exception($mensaje_error);
   252→            }
   253→
   254→            $mensaje_id = $datos['data']['messageId'] ?? null;
   255→            $notificacion->marcarComoEnviado($mensaje_id);
   256→
   257→            return [
   258→                'exito'           => true,
   259→                'mensaje_id'      => $mensaje_id,
   260→                'notificacion_id' => $notificacion->id,
   261→                'data'            => $datos['data'] ?? []
   262→            ];
   263→        } catch (RequestException $error) {
   264→            $mensaje_error = $this->extraerMensajeError($error);
   265→            $notificacion->marcarComoFallido($mensaje_error, (string) $error->getCode());
   266→            $this->manejarError($error, 'enviar mensaje');
   267→        }
   268→
   269→        return [
   270→            'exito'           => false,
   271→            'notificacion_id' => $notificacion->id,
   272→            'error'           => 'Error desconocido'
   273→        ];
   274→    }
   275→
   276→    /**
   277→     * Extraer mensaje de error de una excepción de request.
   278→     *
   279→     * @param RequestException $error Excepción de la petición.
