   507→    /**
   508→     * Generar información de la vacante con IA.
   509→     *
   510→     * @param GenerarVacanteIARequest $request Contenido de la petición.
   511→     * @return JsonResponse
   512→     * @author Daniel Beltrán
   513→     */
   514→    public function generarConIA(GenerarVacanteIARequest $request): JsonResponse {
   515→        $codigo    = Response::HTTP_OK;
   516→        $respuesta = [
   517→            'message' => 'Información generada correctamente'
   518→        ];
   519→
   520→        try {
   521→            $empresa = obtenerEmpresaSesion();
   522→
   523→            $datos_ia = [
   524→                'descripcion' => $request->descripcion
   525→            ];
   526→
   527→            if ($empresa && $empresa->ciudad) {
   528→                $datos_ia['ciudad'] = $empresa->ciudad->nombre;
   529→
   530→                if ($empresa->ciudad->departamento && $empresa->ciudad->departamento->pais) {
   531→                    $datos_ia['pais'] = $empresa->ciudad->departamento->pais->nombre;
   532→                }
   533→            }
   534→
   535→            $respuesta_ia = $this->realizarPeticionIA(
   536→                ruta: 'generar-vacante',
   537→                parametros: $datos_ia,
   538→                contexto_tracking: [
   539→                    'vacante_id' => $request->vacante_id ?? null,
   540→                ]
   541→            );
   542→
   543→            // Extraer solo el 'data' de la respuesta de IA (que ya incluye data y usage)
   544→            $respuesta['data'] = $respuesta_ia['data'] ?? $respuesta_ia;
   545→        } catch (Exception $error) {
   546→            $codigo    = Response::HTTP_BAD_REQUEST;
   547→            $respuesta = [
   548→                'message' => 'Ocurrió un error',
   549→                'errors'  => $error->getMessage()
   550→            ];
   551→        }
   552→
   553→        return new JsonResponse($respuesta, $codigo);
   554→    }
