    53→/**
    54→ * Buscar plantilla de WhatsApp por nombre o ID
    55→ *
    56→ * @param {Array} plantillas Lista de plantillas disponibles
    57→ * @param {Object} configuracion Configuración de la plantilla a buscar
    58→ * @returns {Object|null} Plantilla encontrada o null
