    60→function buscarPlantillaWhatsApp(plantillas, configuracion) {
    61→    if (!plantillas || plantillas.length === 0) {
    62→        return null;
    63→    }
    64→
    65→    if (configuracion.id) {
    66→        let por_id = plantillas.find(plantilla => plantilla.id == configuracion.id);
    67→        if (por_id) return por_id;
    68→    }
    69→
    70→    if (configuracion.nombre) {
    71→        let por_nombre = plantillas.find(plantilla => plantilla.nombre === configuracion.nombre);
    72→        if (por_nombre) return por_nombre;
    73→    }
    74→
    75→    return null;
    76→}
